278	    /**
279	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
280	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
281	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
282	     * elapsed from the birth date to the registration date (defaulting to the server's current date
283	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
284	     *
285	     * @return the age band, or {@code null} when the birth date is absent
286	     */
287	    public String getAgeBand() {
288	        if (this.birthDate == null) {
289	            return null;
290	        }
291	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
292	        int years = Period.between(this.birthDate, asAt).getYears();
293	        if (years < 18) {
294	            return "MINOR";
295	        }
296	        if (years < 65) {
297	            return "ADULT";
298	        }
299	        return "SENIOR";
300	    }
