310	    /**
311	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
312	     * the last two digits of the {@link #getFiscalYear() fiscal year} of the registration date
313	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own customer code and registration
314	     * date; {@code null} when either is absent.
315	     *
316	     * @return the membership number, or {@code null} when it cannot be derived
317	     */
318	    public String getMembershipNumber() {
319	        if (this.customerCode == null || this.registrationDate == null) {
320	            return null;
321	        }
322	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
323	    }
324	
325	    /**
326	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
327	     * the fiscal year of the {@link #getRegistrationDate() business-day-adjusted registration date}.
328	     * The fiscal year starts on 1 July and is named by the calendar year in which it ends, so a
329	     * registration date on or after 1 July belongs to the following calendar year's fiscal year
330	     * (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an earlier date stays in the current one
331	     * (e.g. {@code 2026-06-15} is {@code 'FY26'}). Returns {@code null} when the registration date is
332	     * absent.
333	     *
334	     * @return the fiscal year, or {@code null} when the registration date is absent
335	     */
336	    public String getFiscalYear() {
337	        if (this.registrationDate == null) {
338	            return null;
339	        }
340	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
341	    }
342	
343	    /**
344	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
345	     * is named by the calendar year in which it ends: a date in July through December belongs to the
346	     * next calendar year's fiscal year, while January through June stays in the current one.
347	     *
348	     * @param date the date to classify
349	     * @return the fiscal year as a four-digit calendar year
350	     */
351	    private static int fiscalYearOf(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
354	
355	    /**
356	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
357	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
358	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
359	     *
360	     * @return the Luhn check digit, or {@code null} when the customer code is absent
361	     */
362	    public Integer getCheckDigit() {
363	        if (this.customerCode == null) {
364	            return null;
365	        }
366	        int sum = 0;
367	        boolean dbl = true;
368	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
369	            char c = this.customerCode.charAt(i);
370	            if (c < '0' || c > '9') {
371	                continue;
372	            }
373	            int d = c - '0';
374	            if (dbl) {
375	                d *= 2;
376	                if (d > 9) {
377	                    d -= 9;
378	                }
379	            }
380	            sum += d;
381	            dbl = !dbl;
382	        }
383	        return (10 - (sum % 10)) % 10;
384	    }
385	
386	    /**
387	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
388	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
389	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
390	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
391	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
392	     * tenure, the tenure points are never awarded at create time.
393	     *
394	     * @return the membership points, a non-negative integer
395	     */
396	    public Integer getMembershipPoints() {
397	        int points = 0;
398	        boolean hasEmail = this.email != null && !this.email.isBlank();
399	        if (hasEmail) {
400	            points += 2;
401	        }
402	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
403	        if (hasNoNamesakes) {
404	            points += 1;
405	        }
406	        if (this.householdSize != null && this.householdSize >= 3) {
407	            points += 2;
408	        }
409	        Long tenureFiscalYears = getTenureFiscalYears();
410	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
411	            points += 3;
412	        }
413	        return points;
414	    }
415	
416	    /**
417	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
418	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
419	     * for 6 or more points.
420	     *
421	     * @return the membership level, an integer from 1 to 4
422	     */
423	    public Integer getMembershipLevel() {
424	        int points = getMembershipPoints();
425	        if (points <= 1) {
426	            return 1;
427	        }
428	        if (points <= 3) {
429	            return 2;
430	        }
431	        if (points <= 5) {
432	            return 3;
433	        }
434	        return 4;
435	    }
436	
437	    /**
438	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
439	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
440	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
441	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
442	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
443	     * yet.
444	     *
445	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
446	     */
447	    public Long getTenureFiscalYears() {
448	        if (this.registrationDate == null) {
449	            return null;
450	        }
451	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
452	    }
453	
454	    /**
455	     * The owner's locality, the canonical region string. Once the owner has a
456	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
457	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
458	     * source of truth. Before the customer code is assigned (for example while a create is still
459	     * validating the postcode) it falls back to the region the code will be built from: the
460	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
461	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
462	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
463	     *
464	     * @return the canonical region string, or {@code 'UNKNOWN'}
465	     */
466	    public String getLocality() {
467	        if (this.customerCode != null) {
468	            int dash = this.customerCode.indexOf('-');
469	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
470	        }
471	        return deriveRegion();
472	    }
473	
474	    /**
475	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
476	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
477	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
478	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
479	     *
480	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
481	     */
482	    public String getTimezone() {
483	        return REGION_TIMEZONE.get(getLocality());
484	    }
485	
486	    /**
487	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
488	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
489	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
490	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
491	     * the same region for known cities but disambiguates cities that share a name.
492	     *
493	     * @return the canonical region string, or {@code 'UNKNOWN'}
494	     */
495	    private String deriveRegion() {
496	        String region = regionFromPostcode();
497	        if (region != null) {
498	            return region;
499	        }
500	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
501	    }
502	
503	    /**
504	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
505	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
506	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
507	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
508	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
509	     * owner's region, telephone and last name. Call this once at create time and store the result via
510	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
511	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
512	     *
513	     * @return the assembled customer code
514	     */
515	    public String buildCustomerCode() {
516	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
517	    }
518	
519	    /**
520	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
521	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
522	     *
523	     * @param value the value to hash
524	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
525	     */
526	    private static String sha256Hex8(String value) {
527	        try {
528	            byte[] digest = MessageDigest.getInstance("SHA-256")
529	                .digest(value.getBytes(StandardCharsets.UTF_8));
530	            StringBuilder hex = new StringBuilder(8);
531	            for (int i = 0; i < 4; i++) {
532	                hex.append(String.format("%02X", digest[i]));
533	            }
534	            return hex.toString();
535	        }
536	        catch (NoSuchAlgorithmException e) {
537	            throw new IllegalStateException("SHA-256 algorithm not available", e);
538	        }
539	    }
540	
541	    /**
542	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
543	     * absent, not a 4-digit number, or in no known range.
544	     *
545	     * @return the matching region, or {@code null}
546	     */
547	    private String regionFromPostcode() {
548	        if (this.postcode == null) {
549	            return null;
550	        }
551	        int value;
552	        try {
553	            value = Integer.parseInt(this.postcode.trim());
554	        }
555	        catch (NumberFormatException ex) {
556	            return null;
557	        }
558	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
559	            int[] range = entry.getValue();
560	            if (value >= range[0] && value <= range[1]) {
561	                return entry.getKey();
562	            }
563	        }
564	        return null;
565	    }
566	
567	    /**
568	     * The owner's preferred contact channel, derived from the owner's details. Returns
569	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
570	     *
571	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
572	     */
573	    public String getContactPreference() {
574	        boolean hasEmail = this.email != null && !this.email.isBlank();
575	        return hasEmail ? "EMAIL" : "PHONE";
576	    }
577	
578	    /**
579	     * The owner's identity key, the single derived value used for duplicate detection. It is the
580	     * owner's normalized telephone, email (empty when absent) and household id joined with
581	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
582	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
583	     * are equal, so two members of the same household with different telephones differ here and are
584	     * both allowed.
585	     *
586	     * @return the derived identity key
587	     */
588	    public String getIdentityKey() {
589	        return (this.telephone == null ? "" : this.telephone) + "|"
590	            + (this.email == null ? "" : this.email) + "|"
591	            + (this.householdId == null ? "" : this.householdId);
592	    }
