454	    /**
455	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
456	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
457	     * what gets stored and returned.
458	     *
459	     * @param telephone the raw telephone value from the request
460	     * @return the normalized E.164 telephone number
461	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
462	     */
463	    private String normalizeTelephone(String telephone) {
464	        String e164 = toE164(telephone);
465	        if (e164 == null) {
466	            throw new InvalidOwnerFieldsException(List.of("telephone"));
467	        }
