471	    /**
472	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
473	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
474	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
475	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
476	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
477	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
478	     *
479	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
480	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
481	     *
482	     * @param telephone the raw telephone value, possibly {@code null}
483	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
484	     */
485	    private String toE164(String telephone) {
486	        if (telephone == null) {
487	            return null;
488	        }
489	        String cleaned = telephone.replaceAll("[ \\-()]", "");
490	        String digits;
491	        if (cleaned.startsWith("+")) {
492	            digits = cleaned.substring(1);
493	        } else {
494	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
495	            digits = "61" + national;
496	        }
497	        if (!digits.matches("[0-9]{8,15}")) {
498	            return null;
499	        }
500	        if (!nationalNumberLengthValid(digits)) {
501	            return null;
502	        }
503	        return "+" + digits;
504	    }
505	
506	    /**
507	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
508	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
509	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
510	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
511	     * accepted, leaving only the generic total-length rule to apply.
512	     *
513	     * @param digits the E.164 digits without the leading {@code '+'}
514	     * @return {@code true} if the national-number length matches the country code's requirement
515	     */
516	    private boolean nationalNumberLengthValid(String digits) {
517	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
518	            String code = entry.getKey();
519	            if (digits.startsWith(code)) {
520	                return digits.length() - code.length() == entry.getValue();
521	            }
522	        }
523	        return true;
524	    }
