575	    /**
576	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
577	     * When the computed code is unique it is returned unchanged. When it collides with an existing
578	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
579	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
580	     * so on), and that de-duplicated code is returned.
581	     *
582	     * @param customerCode the freshly computed customer code to de-duplicate
583	     * @return a customer code not held by any existing owner
584	     */
585	    private String deduplicateCustomerCode(String customerCode) {
586	        Set<String> inUse = this.clinicService.findAllOwners().stream()
587	            .map(Owner::getCustomerCode)
588	            .filter(Objects::nonNull)
589	            .collect(Collectors.toSet());
590	        if (!inUse.contains(customerCode)) {
591	            return customerCode;
592	        }
593	        int n = 2;
594	        String candidate;
595	        do {
596	            candidate = customerCode + "-" + n;
597	            n++;
598	        } while (inUse.contains(candidate));
599	        return candidate;
600	    }
