651	        }
652	        String householdId = owner.getHouseholdId();
653	        boolean inUse = this.clinicService.findAllOwners().stream()
654	            .filter(existing -> !existing.isDeleted())
655	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
