667	     * @param owner the owner being created, with its deterministic {@code householdId} already set
668	     */
669	    private void stampHouseholdSize(Owner owner) {
670	        String householdId = owner.getHouseholdId();
671	        List<Owner> members = this.clinicService.findAllOwners().stream()
672	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
673	            .toList();
674	        int householdSize = members.size() + 1;
675	        owner.setHouseholdSize(householdSize);
676	        for (Owner member : members) {
677	            member.setHouseholdSize(householdSize);
678	            this.clinicService.saveOwner(member);
