682	    /**
683	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
684	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
685	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
686	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
687	     * shares a last name and postcode computes the same identifier and therefore the same household.
688	     *
689	     * @param lastName the last name of the household
690	     * @param postcode the postcode of the household, possibly {@code null}
691	     * @return the 12-character upper-case hex household identifier
692	     */
693	    private String computeHouseholdId(String lastName, String postcode) {
694	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
695	        try {
696	            byte[] digest = MessageDigest.getInstance("SHA-256")
697	                .digest(key.getBytes(StandardCharsets.UTF_8));
698	            StringBuilder hex = new StringBuilder(12);
699	            for (int i = 0; i < 6; i++) {
700	                hex.append(String.format("%02X", digest[i]));
701	            }
702	            return hex.toString();
703	        } catch (NoSuchAlgorithmException e) {
704	            throw new IllegalStateException("SHA-256 algorithm not available", e);
705	        }
706	    }
