708	    /**
709	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
710	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
711	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
712	     *
713	     * @param value the raw value, possibly {@code null}
714	     * @return the normalized value
715	     */
716	    private String normalizeForHousehold(String value) {
717	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
718	    }
