720	    /**
721	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
722	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
723	     * value yields an empty string.
724	     *
725	     * @param value the raw value, possibly {@code null}
726	     * @return the trimmed, whitespace-collapsed value
727	     */
728	    private String collapseWhitespace(String value) {
729	        if (value == null) {
730	            return "";
731	        }
732	        return value.trim().replaceAll("\\s+", " ");
733	    }
