735	    /**
736	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
737	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
738	     * is upper-cased, and common street-type abbreviations are expanded as whole words
739	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
740	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
741	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
742	     *
743	     * @param address the raw address value, possibly {@code null}
744	     * @return the normalized address
745	     */
746	    private String normalizeAddress(String address) {
747	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
748	        if (collapsed.isEmpty()) {
749	            return "";
750	        }
751	        String[] tokens = collapsed.split(" ");
752	        StringBuilder normalized = new StringBuilder();
753	        for (int i = 0; i < tokens.length; i++) {
754	            if (i > 0) {
755	                normalized.append(' ');
756	            }
757	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
758	        }
759	        return normalized.toString();
760	    }
