762	    /**
763	     * Applies the owner's address from the request, preferring the structured form over the flat one.
764	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
765	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
766	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
767	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
768	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
769	     * the structured address when present, falling back to the flat address.
770	     *
771	     * @param owner the owner being created
772	     * @param ownerFieldsDto the submitted owner fields
773	     */
774	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
775	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
776	        if (StringUtils.hasText(line1)) {
777	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
778	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
779	            owner.setAddressLine1(line1);
780	            owner.setAddressLine2(normalizedLine2);
781	            owner.setAddress(composeAddress(line1, normalizedLine2));
782	        } else {
783	            owner.setAddressLine1(null);
784	            owner.setAddressLine2(null);
785	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
786	        }
787	    }
