789	    /**
790	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
791	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
792	     * appended when the second line is present.
793	     *
794	     * @param line1 the normalized first address line
795	     * @param line2 the normalized second address line, or {@code null} when absent
796	     * @return the composed address string
797	     */
798	    private String composeAddress(String line1, String line2) {
799	        return line2 == null ? line1 : line1 + " " + line2;
800	    }
