870	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
871	        HttpHeaders headers = new HttpHeaders();
872	        Visit visit = visitMapper.toVisit(visitFieldsDto);
873	        Pet pet = new Pet();
874	        pet.setId(petId);
875	        visit.setPet(pet);
876	        this.clinicService.saveVisit(visit);
877	        VisitDto visitDto = visitMapper.toVisitDto(visit);
878	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
879	            .buildAndExpand(visit.getId()).toUri());
880	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
881	    }
882	
883	
884	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
885	    @Override
886	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
887	        Owner owner = this.clinicService.findOwnerById(ownerId);
888	        if (owner != null) {
889	            Pet pet = owner.getPet(petId);
890	            if (pet != null) {
891	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
892	            }
893	        }
894	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
895	    }
